function renderImages(){$("imagesTable").innerHTML='<table><thead><tr><th>Preview</th><th>Kunci gambar</th><th>URL publik</th><th>Aksi</th></tr></thead><tbody>'+images.map(i=>'<tr><td><img class="cover" src="'+esc(i.image_url)+'" alt="'+esc(i.image_key)+'"></td><td><b>'+esc(i.image_key)+'</b></td><td><input readonly value="'+esc(i.image_url)+'" aria-label="URL gambar '+esc(i.image_key)+'"></td><td><button type="button" data-copy-image="'+esc(i.image_url)+'">Salin URL</button> <button type="button" class="danger" data-delete-image="'+esc(i.image_key)+'">Hapus gambar</button></td></tr>').join("")+'</tbody></table><p class="muted">Hapus gambar akan menghapus file dari Storage Supabase juga. Gambar yang masih dipakai game atau promo akan dilindungi.</p>';}async function saveHomepagePart(part){if(!homepageSettings){say("Pengaturan beranda belum tersedia.");return;}const payload={updated_at:new Date().toISOString()};if(part==="trending"){payload.trending_slugs=Array.from($("homepageGamesTable").querySelectorAll("[data-trending-slug]:checked")).map(el=>({slug:el.dataset.trendingSlug,order:Number($("homepageGamesTable").querySelector('[data-trending-order="'+el.dataset.trendingSlug+'"]')?.value)||99999})).sort((a,b)=>a.order-b.order||a.slug.localeCompare(b.slug)).map(item=>item.slug);payload.trending_title=$("homeTrendingTitle").value.trim()||"Trending";payload.trending_limit=Number($("homeTrendingLimit").value)||6;payload.trending_enabled=$("homeTrendingEnabled").value==="true";if(!payload.trending_slugs.length&&payload.trending_enabled&&!confirm("Belum ada game yang dipilih untuk Trending. Simpan agar bagian Trending kosong?"))return;}else{payload.all_games_title=$("homeAllTitle").value.trim()||"All Games";payload.all_games_initial_limit=Number($("homeAllLimit").value)||12;payload.all_games_enabled=$("homeAllEnabled").value==="true";payload.show_all_games_button=$("homeShowAllButton").value==="true";payload.all_games_slugs=Array.from($("homepageAllGamesTable").querySelectorAll("[data-allgame-slug]:checked")).map(el=>({slug:el.dataset.allgameSlug,order:Number($("homepageAllGamesTable").querySelector('[data-allgame-order="'+el.dataset.allgameSlug+'"]')?.value)||99999})).sort((a,b)=>a.order-b.order||a.slug.localeCompare(b.slug)).map(item=>item.slug);if(!payload.all_games_slugs.length&&!confirm("Belum ada game yang dipilih untuk All Games. Home akan menampilkan semua game tersedia berdasarkan urutan katalog. Lanjutkan?"))return;}const {error}=await db.from("store_homepage_settings").update(payload).eq("id",1);if(error){say("Gagal menyimpan "+(part==="trending"?"Trending":"All Games")+": "+error.message);return;}homepageSettings={...homepageSettings,...payload};renderHomepage();say("Pengaturan "+(part==="trending"?"Trending":"All Games")+" tersimpan. Muat ulang Home untuk melihat perubahan.");}$("saveTrending").onclick=()=>saveHomepagePart("trending");$("saveAllGames").onclick=()=>saveHomepagePart("allgames");document.addEventListener("DOMContentLoaded",()=>{const loginPanel=$("loginPanel");if(loginPanel)loginPanel.classList.add("hidden");});
