function previewGameImage(kind,url){const wrap=$(kind==="icon"?"gIconPreviewWrap":"gBannerPreviewWrap"),img=$(kind==="icon"?"gIconPreview":"gBannerPreview");if(!url){img.removeAttribute("src");wrap.classList.remove("has-image");return;}img.onload=()=>wrap.classList.add("has-image");img.onerror=()=>{wrap.classList.remove("has-image");say("Preview gambar "+(kind==="icon"?"ikon":"banner")+" gagal dimuat. Periksa URL atau upload ulang.");};img.src=url;}
