function previewLocalImage(inputId,kind){const input=$(inputId),file=input.files&&input.files[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){say("Format file harus JPG, PNG, atau WebP.");input.value="";return;}const max=kind==="currency"?5:50;if(file.size>max*1024*1024){say("Ukuran file maksimal "+max+" MB.");input.value="";return;}const url=URL.createObjectURL(file),img=$(kind==="currency"?"gCurrencyIconPreview":kind==="icon"?"gIconPreview":"gBannerPreview");img.addEventListener("load",()=>URL.revokeObjectURL(url),{once:true});img.addEventListener("error",()=>URL.revokeObjectURL(url),{once:true});if(kind==="currency"){$("gCurrencyIcon").value="";$("gCurrencyIconPicker").value="";previewCurrencyIcon(url);}else{const field=kind==="icon"?"gIcon":"gBanner",picker=kind==="icon"?"gIconPicker":"gBannerPicker";$(field).value="";$(picker).value="";previewGameImage(kind,url);}say("Preview "+(kind==="currency"?"ikon default produk":kind==="icon"?"gambar game":"banner checkout")+" tampil. Tekan tombol Upload untuk menyimpan ke perpustakaan gambar.");}
