async function uploadProductIconFile(file,productId,gameSlug){if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>5*1024*1024){say("Gunakan JPG, PNG, atau WebP maksimal 5 MB.");return null;}const safe=String(productId||"produk").replace(/[^a-z0-9_-]/gi,"-"),slug=String(gameSlug||"game").replace(/[^a-z0-9-]/gi,"-"),ext=(file.name.split(".").pop()||"webp").toLowerCase().replace(/[^a-z0-9]/g,"")||"webp",path="product-icons/"+slug+"-"+safe+"-"+Date.now()+"."+ext;const up=await db.storage.from("leo-store-images").upload(path,file,{upsert:false,contentType:file.type});if(up.error){say("Upload ikon produk gagal: "+up.error.message);return null;}const url=db.storage.from("leo-store-images").getPublicUrl(path).data.publicUrl;const key="product-icon-"+safe+"-"+Date.now();const saved=await db.from("store_images").upsert({image_key:key,image_url:url,updated_at:new Date().toISOString()},{onConflict:"image_key"});if(saved.error){say("File terunggah, tetapi perpustakaan gambar gagal diperbarui: "+saved.error.message);return null;}await loadAll();return url;}
$("uploadProductIcon").onclick=async()=>{const file=$("pIconFile").files[0];if(!file){say("Pilih ikon produk terlebih dahulu.");return;}const id=$("pId").value.trim()||"produk-baru",slug=$("pGame").value||"game",url=await uploadProductIconFile(file,id,slug);if(!url)return;$("pIcon").value=url;$("pIconPicker").value=url;previewProductIcon(url);say("Ikon produk terunggah. Tekan Tambah produk untuk menyimpan produk dengan ikon ini.");};
function previewCurrencyIcon(url){const w=$("gCurrencyIconPreviewWrap"),im=$("gCurrencyIconPreview");if(!url){im.removeAttribute("src");w.classList.remove("has-image");return;}im.onload=()=>w.classList.add("has-image");im.onerror=()=>w.classList.remove("has-image");im.src=url;}
