async function uploadCurrencyIcon(){const file=$("gCurrencyIconFile").files[0];if(!file){say("Pilih ikon mata uang terlebih dahulu.");return;}if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>5*1024*1024){say("Gunakan JPG, PNG, atau WebP maksimal 5 MB.");return;}const dims=await new Promise(resolve=>{const im=new Image();im.onload=()=>resolve({w:im.naturalWidth,h:im.naturalHeight});im.onerror=()=>resolve(null);im.src=URL.createObjectURL(file);});if(!dims||Math.abs(dims.w/dims.h-1)>0.03){say("Ikon mata uang harus persegi 1:1.");return;}const slug=($("gSlug").value||"game").replace(/[^a-z0-9-]/gi,"-"),ext=file.name.split(".").pop().toLowerCase().replace(/[^a-z0-9]/g,"")||"webp",path="currency-icons/"+slug+"-"+Date.now()+"."+ext;const up=await db.storage.from("leo-store-images").upload(path,file,{upsert:false,contentType:file.type});if(up.error){say("Upload ikon gagal: "+up.error.message);return;}const url=db.storage.from("leo-store-images").getPublicUrl(path).data.publicUrl;const saved=await db.from("store_images").upsert({image_key:"currency-icon-"+slug,image_url:url,updated_at:new Date().toISOString()},{onConflict:"image_key"});if(saved.error){say("Gambar terunggah, tetapi perpustakaan gambar gagal diperbarui: "+saved.error.message);return;}await loadAll();$("gCurrencyIcon").value=url;$("gCurrencyIconPicker").value=url;previewCurrencyIcon(url);say("Ikon mata uang berhasil diunggah. Tekan Simpan game untuk menerapkan.");}
$("uploadCurrencyIcon").onclick=uploadCurrencyIcon;
async function uploadGameImage(kind){const isIcon=kind==="icon",file=$(isIcon?"gIconFile":"gBannerFile").files[0];if(!file){say("Pilih file "+(isIcon?"ikon":"banner checkout")+" terlebih dahulu.");return;}if(!/^image\/(jpeg|png|webp)$/.test(file.type)){say("Format file harus JPG, PNG, atau WebP.");return;}if(file.size>50*1024*1024){say("Ukuran file maksimal 50 MB.");return;}const slug=$("gSlug").value.trim().toLowerCase().replace(/[^a-z0-9-]/g,"-").replace(/-+/g,"-").replace(/^-|-$/g,"")||"game";const dimensions=await new Promise(resolve=>{const im=new Image();im.onload=()=>resolve({w:im.naturalWidth,h:im.naturalHeight});im.onerror=()=>resolve(null);im.src=URL.createObjectURL(file);});if(!dimensions){say("File gambar tidak bisa dibaca.");return;}const ratio=dimensions.w/dimensions.h,expected=isIcon?1:16/9;if(Math.abs(ratio-expected)>(isIcon?0.02:0.035)){say((isIcon?"Ikon harus 1:1 (persegi).":"Banner checkout harus 16:9 (landscape).")+" Ukuran file saat ini "+dimensions.w+" × "+dimensions.h+". Sesuaikan/crop gambar lalu upload lagi.");return;}const ext=file.name.split(".").pop().toLowerCase().replace(/[^a-z0-9]/g,"")||"webp",path="game-"+(isIcon?"icons":"banners")+"/"+slug+"-"+Date.now()+"."+ext;say("Mengunggah "+(isIcon?"ikon":"banner checkout")+"…");const up=await db.storage.from("leo-store-images").upload(path,file,{upsert:false,contentType:file.type});if(up.error){say("Upload gagal: "+up.error.message);return;}const url=db.storage.from("leo-store-images").getPublicUrl(path).data.publicUrl;const field=isIcon?"gIcon":"gBanner";$(field).value=url;previewGameImage(kind,url);const key="game-"+(isIcon?"icon-":"checkout-banner-")+slug;const saved=await db.from("store_images").upsert({image_key:key,image_url:url,updated_at:new Date().toISOString()},{onConflict:"image_key"});if(saved.error){say("File terunggah dan URL sudah diisi, tetapi perpustakaan gambar gagal diperbarui: "+saved.error.message+". Tekan Simpan game untuk menyimpan URL.");return;}await loadAll();$(field).value=url;if(isIcon)$("gIconPicker").value=url;say("Upload berhasil. URL "+(isIcon?"ikon":"banner checkout")+" sudah terisi; tekan Tambah / simpan game untuk menerapkannya.");}
