$("importLegacyBanners").onclick=async()=>{const btn=$("importLegacyBanners");btn.disabled=true;say("Menyiapkan banner bawaan…");try{const base="https://leovbr.github.io/Leo-store/";const defaults=[{title:"Mobile Legends",description:"TOP UP SEKARANG",image_url:base+"assets/icons/mobile-legends.webp",target_url:base+"checkout.html?game=mobile-legends",sort_order:0},{title:"Free Fire",description:"TOP UP SEKARANG",image_url:base+"assets/icons/free-fire.webp",target_url:base+"checkout.html?game=free-fire",sort_order:1},{title:"PUBG Mobile",description:"TOP UP SEKARANG",image_url:base+"assets/icons/pubg-mobile.webp",target_url:base+"checkout.html?game=pubg-mobile",sort_order:2}];const known=new Set(promos.map(p=>(p.title||"").trim().toLowerCase()));const missing=defaults.filter(p=>!known.has(p.title.toLowerCase()));if(!missing.length){say("Banner bawaan sudah terdaftar. Lihat daftar di bawah lalu pilih Edit atau Aktifkan.");return;}const now=Date.now(),hasActive=promos.some(p=>p.is_active&&p.image_url&&p.target_url&&(!p.starts_at||new Date(p.starts_at).getTime()<=now)&&(!p.ends_at||new Date(p.ends_at).getTime()>=now));let inserted=0;for(const p of missing){const {error}=await db.from("store_promos").insert({...p,discount_type:"none",discount_value:0,is_active:!hasActive});if(error){say("Gagal memasukkan "+p.title+": "+error.message+" ("+inserted+" banner berhasil ditambahkan)");return;}inserted++;}say(inserted+" banner bawaan berhasil dimasukkan. "+(hasActive?"Banner baru dibuat nonaktif agar tidak menggandakan banner aktif.":"Banner baru aktif."));await loadAll();}catch(err){say("Impor banner gagal: "+(err?.message||String(err)));}finally{btn.disabled=false;}};
$("addPromo").onclick=async()=>{
 const btn=$("addPromo");
 if(btn.disabled)return;
 btn.disabled=true;
 say("Memproses penyimpanan banner…");
 try{
  const title=$("promoTitle").value.trim(),description=$("promoDesc").value.trim();
  const imageUrl=$("promoImage").value.trim();
  const mode=$("promoTargetPreset").value;
  let targetUrl=$("promoTarget").value.trim();
  if(mode==="home")targetUrl="https://leovbr.github.io/Leo-store/index.html";
  else if(mode==="shop")targetUrl="https://leovbr.github.io/Leo-store/shop.html";
  else if(mode==="order")targetUrl="https://leovbr.github.io/Leo-store/order.html";
  else if(mode==="game"){
   const slug=$("promoTargetGame").value;
   if(!slug){say("Pilih game tujuan checkout terlebih dahulu.");$("promoTargetGame").classList.remove("hidden");$("promoTargetGame").scrollIntoView({behavior:"smooth",block:"center"});$("promoTargetGame").focus();return;}
   targetUrl="https://leovbr.github.io/Leo-store/checkout.html?game="+encodeURIComponent(slug);
  }else if(mode==="custom")targetUrl=$("promoTarget").value.trim();
  if(!targetUrl&&mode!=="custom"){targetUrl="https://leovbr.github.io/Leo-store/index.html";$("promoTargetPreset").value="home";}
  if(!targetUrl&&mode==="custom"){say("Masukkan URL tujuan sendiri atau pilih tujuan otomatis seperti Beranda.");$("promoTarget").focus();return;}
  $("promoTarget").value=targetUrl;
  const validHttpUrl=/^https?:\/\/[^\s/$.?#][^\s]*$/i.test(targetUrl);
  if(!validHttpUrl){say("URL tujuan tidak valid. Pilih tujuan otomatis atau isi URL lengkap yang diawali http:// atau https://.");if(mode==="custom")$("promoTarget").focus();return;}
  if(!imageUrl){say("Gambar belum dipilih. Pilih gambar dari perpustakaan atau upload foto banner terlebih dahulu.");$("promoImagePicker").scrollIntoView({behavior:"smooth",block:"center"});return;}
  const iso=id=>$(id).value?new Date($(id).value).toISOString():null;
  const payload={title,description,image_url:imageUrl,target_url:targetUrl,discount_type:$("promoType").value,discount_value:Number($("promoValue").value)||0,starts_at:iso("promoStart"),ends_at:iso("promoEnd"),sort_order:Number($("promoOrder").value)||0,is_active:true};
  if(payload.ends_at&&payload.starts_at&&payload.ends_at<payload.starts_at){say("Waktu selesai harus setelah waktu mulai.");return;}
  say(editingPromoId?"Menyimpan perubahan banner ke database…":"Menyimpan banner baru ke database…");
  const result=editingPromoId
   ?await db.from("store_promos").update(payload).eq("id",editingPromoId)
   :await db.from("store_promos").insert(payload);
  if(result.error){say("GAGAL MENYIMPAN BANNER: "+result.error.message);return;}
  say(editingPromoId?"Banner / promo berhasil diperbarui.":"Banner / promo berhasil ditambahkan.");
  resetPromoForm();
  await loadAll();
 }catch(err){
  say("ERROR saat menyimpan banner: "+(err&&err.message?err.message:String(err))+". Coba tekan sekali lagi; jika berulang, kirim teks status ini.");
 }finally{
  btn.disabled=false;
 }
};
